const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const time=s=>/^\d{4}-\d{2}-\d{2}$/.test(s||'')?s+' · 날짜 기준':s&&Number.isFinite(Date.parse(s))?new Intl.DateTimeFormat('ko-KR',{dateStyle:'short',timeStyle:'short',timeZone:'Asia/Seoul'}).format(new Date(s))+' KST':'시각 미확인';
const labels={fact:'자료에서 확인',calculation:'계산',analysis:'분석',assumption:'가정',unknown:'추가 확인'};
const examples=['삼성전자를 저장된 재무·리포트와 매출 비중으로 분석해줘','MSFT의 사업별 매출 비중과 현금흐름은 어때?','금리가 내려가고 환율이 오르면 기업에 어떤 영향이 있을까?','코인 가격 상승과 프로토콜 성장의 차이는?'];
export function chatQuotaText(q){
 if(!q)return '이용 한도를 불러오지 못했습니다.';
 const at=q.retryAt?new Intl.DateTimeFormat('ko-KR',{month:'long',day:'numeric',hour:'numeric',minute:'2-digit',second:'2-digit',timeZone:'Asia/Seoul'}).format(new Date(Math.ceil(Date.parse(q.retryAt)/1000)*1000)):null;
 return `최근 1시간 ${q.used}/${q.limit}회 사용 · ${q.remaining}회 남음${at?` · ${at} KST부터 다시 이용 가능`:''}`;
}
export function chatText(text){
 // Escape first; only safe typography. No model HTML, URLs, images, scripts or dynamic charts.
 const inline=s=>s.replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>');
 return esc(text).split(/\n\n+/).map(p=>{const lines=p.split('\n'),cells=s=>s.trim().replace(/^\||\|$/g,'').split('|').map(x=>inline(x.trim()));
  if(lines.length>=2&&lines[0].includes('|')&&/^\s*\|?\s*:?-{3,}/.test(lines[1])&&cells(lines[1]).every(c=>/^:?-{3,}:?$/.test(c))){const head=cells(lines[0]);return `<div class="chat-table-wrap" tabindex="0" aria-label="비교표 가로 스크롤"><table><thead><tr>${head.map(c=>`<th scope="col">${c}</th>`).join('')}</tr></thead><tbody>${lines.slice(2,18).map(line=>`<tr>${cells(line).slice(0,head.length).map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
  return `<p>${inline(p).replaceAll('\n','<br>')}</p>`;
 }).join('');
}
function sourceMarkup(s,turn){return `<li id="chat-source-${esc(turn)}-${esc(s.id)}"><strong>${esc(s.id)} · ${s.url?`<a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)} ↗</a>`:esc(s.title)}</strong><small>발행 ${esc(time(s.publishedAt))} · 조회 ${esc(time(s.observedAt))}</small>${s.kind==='market'?'<small>저장된 시세입니다. 현재가와 다를 수 있습니다.</small>':''}${s.coverage?`<small>${esc(s.coverage)}</small>`:''}${/^\/reports\?report=-?\d+%3A\d+$/.test(s.reportPath||'')?`<a href="${esc(s.reportPath)}" data-nav>사이트에서 리포트 보기 →</a>`:''}${s.sourceUrls?.map(u=>`<a href="${esc(u)}" target="_blank" rel="noopener noreferrer">${s.kind==='report_notice'?'게시 출처':'계산 원자료'} ↗</a>`).join('')||''}</li>`;}
export function chatCoverageMarkup(coverage=[]){
 const names={business:'사업·매출 구성',financials:'재무',reports:'리포트'},states={available:'확인',not_available:'저장 자료 부족',read_failed:'조회 오류',evidence_limit:'조회 한도',unavailable:'출처 재확인'};
 const rows=coverage.filter(c=>names[c.dataset]);if(!rows.length)return '';
 return `<details class="chat-sources chat-data-coverage"><summary>참고한 저장 자료</summary><ul>${rows.map(c=>`<li><strong>${esc(c.name)} · ${names[c.dataset]}</strong><small>${states[c.status]||'확인 필요'}${c.status==='available'&&c.refs?.length?` · 근거 ${c.refs.length}개`:''}</small></li>`).join('')}</ul></details>`;
}
export function chatAnswerMarkup(j){
 if(!j.result&&!['queued','running'].includes(j.status))return `<p class="chat-completed">${j.status==='cancelled'?'질문 처리를 중지했습니다.':'답변을 완료하지 못했습니다. 아래에서 다시 질문해 주세요.'}</p>`;
 if(!j.result)return `<div class="chat-progress" role="status"><span class="chat-spinner"></span>질문에 필요한 자료를 확인하고 있습니다.<button type="button" data-chat-cancel="${esc(j.id)}">중지</button></div>`;
 const r=j.result;return `<div class="chat-answer">${r.blocks.map(b=>`<section class="chat-block chat-${esc(b.kind)}"><small>${esc(labels[b.kind])}</small>${chatText(b.text)}${b.refs.length?`<div class="chat-citations">${b.refs.map(id=>`<button type="button" data-chat-source="${esc(id)}">${esc(id)}</button>`).join('')}</div>`:''}</section>`).join('')}${chatCoverageMarkup(r.coverage)}${r.sources.length?`<details class="chat-sources"><summary>출처 ${r.sources.length}개 · 자료 기준 확인</summary><ul>${r.sources.map(s=>sourceMarkup(s,j.id)).join('')}</ul></details>`:''}<div class="chat-followups">${r.followups.map(q=>`<button type="button" data-chat-question="${esc(q)}">${esc(q)}</button>`).join('')}</div>${['complete','limited'].includes(j.status)?`<a class="chat-track-thought" href="/catalyst?thesisDraft=${encodeURIComponent(j.id)}" data-nav>이 생각 계속 추적 →</a>`:''}<small class="chat-completed">${esc(time(j.updatedAt))} · ${j.status==='failed'?'처리 중단':'답변 완료'}</small></div>`;
}
export function chatLocation(id,thesisId=null,cleared=false){const p=new URLSearchParams({chat:id});if(thesisId)p.set('thesisContext',thesisId);else if(cleared)p.set('withoutThesis','1');return '/catalyst?'+p;}
export function mountFreeResearch(root){
 let alive=true,timer=null,parent=null,busy=false,history=[],market='ALL',thesisId=new URLSearchParams(location.search).get('thesisContext'),thesisCleared=new URLSearchParams(location.search).has('withoutThesis'),contextVersion=0;const lifecycle=new AbortController();
 const headers=()=>({'Content-Type':'application/json',...(sessionStorage.getItem('catalyst-admin-token')?{Authorization:'Bearer '+sessionStorage.getItem('catalyst-admin-token')}:{})});
 const api=async(path,options={})=>{const r=await fetch('/api/catalyst/'+path,{...options,headers:headers(),signal:lifecycle.signal});const v=await r.json();if(!r.ok)throw Object.assign(Error(v.message||'요청을 처리하지 못했습니다.'),{code:v.code,quota:v.quota});return v;};
 root.innerHTML=`<div class="research-chat"><header class="chat-heading"><div><span class="eyebrow">INVESTMENT RESEARCH</span><h1>투자 리서치</h1><p>기업·산업·경제의 변화를 질문하고, 근거를 이어서 살펴보세요.</p></div><div class="chat-heading-actions"><a href="/catalyst?theses=1" data-nav>내 투자 생각 →</a><button type="button" class="secondary-button" data-chat-new>새 대화</button></div></header><div class="chat-thesis-context" hidden></div><div class="chat-examples">${examples.map(q=>`<button type="button" data-chat-question="${esc(q)}">${esc(q)}</button>`).join('')}</div><div class="chat-thread" aria-live="polite"></div><p class="chat-error" role="alert" hidden></p><form class="surface chat-form"><label for="research-question">궁금한 점을 자유롭게 물어보세요</label><textarea id="research-question" name="question" rows="3" maxlength="900" placeholder="질문을 입력하세요. 답변을 받은 뒤 조건을 바꾸거나 이어서 물어볼 수 있어요." required></textarea><div><label>시장 <select name="market"><option value="ALL">전체</option><option value="KR">국내 주식</option><option value="US">미국 주식</option><option value="CRYPTO">가상화폐</option></select></label><button class="primary-button" type="submit">질문하기 →</button></div><small>출처와 자료 기준을 확인해 주세요. 현재가·인과관계가 확인되지 않으면 구분해 안내합니다.</small></form><details class="chat-history"><summary>내 최근 대화</summary><ul></ul></details><a class="chat-classic" href="/catalyst?classic=1" data-nav>기존 수혜주 분석 보기 →</a></div>`;
 const form=root.querySelector('form'),input=form.elements.question,error=root.querySelector('.chat-error'),thread=root.querySelector('.chat-thread');
 const quotaBox=document.createElement('div');quotaBox.className='chat-quota';quotaBox.innerHTML='<small role="status">이용 한도 확인 중…</small><button type="button" data-chat-quota-refresh>한도 확인</button>';form.append(quotaBox);
 const showQuota=q=>{quotaBox.querySelector('small').textContent=chatQuotaText(q);if(q?.remaining>0&&error.dataset.code==='CHAT_RATE_LIMIT')error.hidden=true;};
 const showError=e=>{error.hidden=false;error.textContent=e.message;error.dataset.code=e.code||'';if(e.quota)showQuota(e.quota);};
 async function loadThesisContext(){const selected=thesisId,version=++contextVersion,box=root.querySelector('.chat-thesis-context');if(!selected){box.hidden=true;return;}try{const r=await fetch('/api/theses/'+encodeURIComponent(selected),{headers:headers(),signal:lifecycle.signal}),d=await r.json();if(!r.ok)throw Error(d.message||'이어갈 투자 생각을 불러오지 못했습니다.');if(!alive||version!==contextVersion||thesisId!==selected)return;box.hidden=false;box.innerHTML=`<div><strong>내 투자 생각 · 버전 ${esc(d.currentVersion)}</strong><button type="button" data-thesis-context-clear>연결 해제</button></div><p>${esc(d.title)}</p><a href="/catalyst?thesis=${encodeURIComponent(d.id)}" data-nav>저장한 생각과 최근 검토 보기 →</a>`;}catch(e){if(alive&&version===contextVersion){thesisId=null;thesisCleared=true;box.hidden=true;showError(e);}}}
 const render=()=>{const html=history.map(j=>`<article class="surface chat-turn" data-turn="${esc(j.id)}"><h2>${esc(j.query)}</h2>${chatAnswerMarkup(j)}</article>`).join('');if(thread.innerHTML!==html)thread.innerHTML=html;form.querySelector('button[type=submit]').disabled=busy;input.placeholder=parent?'이어서 질문하거나 비교 조건을 바꿔보세요.':'궁금한 투자 질문을 입력하세요.';};
 const recent=async()=>{try{const r=await api('chat');if(alive){showQuota(r.quota);root.querySelector('.chat-history ul').innerHTML=r.items.map(j=>`<li><button type="button" data-chat-load="${esc(j.id)}">${esc(j.query)}</button><small>${esc(time(j.updated_at))}</small></li>`).join('')||'<li>아직 대화가 없습니다.</li>';}}catch{if(alive)showQuota(null);}};
 async function poll(id){try{const j=await api('chat/'+id);if(!alive)return;const i=history.findIndex(x=>x.id===id);if(i>=0)history[i]=j;else history.push(j);busy=['queued','running'].includes(j.status);if(!busy&&['complete','limited'].includes(j.status))parent=j.id;render();if(busy)timer=setTimeout(()=>poll(id),2000);else await recent();}catch(e){if(alive){busy=false;render();showError(e);}}}
 async function load(id){clearTimeout(timer);error.hidden=true;try{const chain=[];let current=id;for(let i=0;current&&i<12;i++){const j=await api('chat/'+current);chain.unshift(j);current=j.parentId;}if(!alive)return;history=chain;const last=chain.at(-1);if(!thesisId&&!thesisCleared&&last.thesisId){thesisId=last.thesisId;void loadThesisContext();window.history.replaceState(null,'',chatLocation(last.id,thesisId));}market=last.market;form.elements.market.value=market;parent=['complete','limited'].includes(last.status)?last.id:last.parentId;busy=['queued','running'].includes(last.status);render();if(busy)poll(last.id);}catch(e){showError(e);}}
 form.addEventListener('submit',async e=>{e.preventDefault();if(busy||!input.value.trim())return;error.hidden=true;busy=true;render();try{const q=input.value.trim();market=form.elements.market.value;const j=await api('chat',{method:'POST',body:JSON.stringify({query:q,market,parentId:parent,...(thesisId?{thesisId}:{})})});if(!alive)return;input.value='';history.push({...j,query:q});window.history.replaceState(null,'',chatLocation(j.id,thesisId,thesisCleared));render();void recent();poll(j.id);}catch(e){busy=false;render();showError(e);}},{signal:lifecycle.signal});
 root.addEventListener('click',async e=>{
  if(e.target.closest('[data-thesis-context-clear]')){thesisId=null;thesisCleared=true;++contextVersion;root.querySelector('.chat-thesis-context').hidden=true;const u=new URL(location.href);u.searchParams.delete('thesisContext');u.searchParams.set('withoutThesis','1');window.history.replaceState(null,'',u);}
  const refresh=e.target.closest('[data-chat-quota-refresh]');if(refresh){refresh.disabled=true;await recent();if(alive)refresh.disabled=false;}
  const question=e.target.closest('[data-chat-question]');if(question){input.value=question.dataset.chatQuestion;input.focus();form.scrollIntoView({block:'nearest',behavior:'smooth'});}
  const source=e.target.closest('[data-chat-source]');if(source){const turn=source.closest('.chat-turn'),details=turn.querySelector('.chat-sources:not(.chat-data-coverage)');if(details){details.open=true;turn.querySelector('#chat-source-'+turn.dataset.turn+'-'+source.dataset.chatSource)?.scrollIntoView({block:'nearest',behavior:'smooth'});}}
  const old=e.target.closest('[data-chat-load]');if(old&&!busy){thesisId=null;thesisCleared=false;++contextVersion;root.querySelector('.chat-thesis-context').hidden=true;window.history.replaceState(null,'',chatLocation(old.dataset.chatLoad));load(old.dataset.chatLoad);}
  if(e.target.closest('[data-chat-new]')&&!busy){parent=null;history=[];thesisId=null;thesisCleared=false;++contextVersion;root.querySelector('.chat-thesis-context').hidden=true;error.hidden=true;window.history.replaceState(null,'','/catalyst');render();input.focus();}
  const cancel=e.target.closest('[data-chat-cancel]');if(cancel){try{await api('chat/'+cancel.dataset.chatCancel+'/cancel',{method:'POST',body:'{}'});}catch(e){showError(e);}}
 },{signal:lifecycle.signal});
 if(thesisId)void loadThesisContext();
 const url=new URL(location.href),id=url.searchParams.get('chat');if(id)void load(id);else if(url.searchParams.get('q'))input.value=url.searchParams.get('q');void recent();
 return {destroy(){alive=false;lifecycle.abort();clearTimeout(timer);}};
}
